// The site icon: the robot face, 180 by 180 PNG, served at /favicon.ico and
// /favicon.png. Directories and browsers that show a site's favicon (Claude's
// connector directory among them) showed a bare letter, because nothing here
// answered either address. Carried as base64 for the same reason as the
// roadmap's share image: the Worker bundles code, not files.
export const FAVICON_PNG_BASE64: string = "";

let iconBytes: Uint8Array | null = null;

export function faviconPng(): Uint8Array {
  if (!iconBytes) {
    const bin = atob(FAVICON_PNG_BASE64);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    iconBytes = out;
  }
  return iconBytes;
}
